/**
 * LoneScale Node - Version 1
 * Discriminator: resource=contact, operation=source
 */


interface Credentials {
  loneScaleApi: CredentialReference;
}

/** Enrich or source contacts */
export type LoneScaleV1ContactSourceParams = {
  resource: 'contact';
  operation: 'source';
/**
 * Company domain to source contacts from. Provide at least one of domain, name or Linkedin URL.
 */
    sourceCompanyDomain?: string | Expression<string>;
/**
 * Company name to source contacts from
 */
    sourceCompanyName?: string | Expression<string>;
/**
 * Company Linkedin URL, increases coverage and accuracy by 25%
 */
    sourceCompanyLinkedinUrl?: string | Expression<string>;
/**
 * Personas
 * @default {}
 */
    personas?: {
        /** Persona
     */
    persona?: Array<{
      /** A label for this persona
       */
      name?: string | Expression<string>;
      /** Comma-separated job titles to match
       */
      jobTitles?: string | Expression<string>;
      /** Comma-separated job titles to exclude
       */
      excludeJobTitles?: string | Expression<string>;
    }>;
  };
/**
 * Additional Fields
 * @default {}
 */
    sourceAdditionalFields?: {
    /** Whether to skip enrichment of company information (industry, size, etc.) for each contact
     * @default false
     */
    disableCompanyInfo?: boolean | Expression<boolean>;
    /** Comma-separated ISO 3166-1 alpha-2 country codes to include
     */
    includedLocations?: string | Expression<string>;
    /** Maximum number of contacts to retrieve (capped at 10)
     * @default 10
     */
    maxResults?: number | Expression<number>;
    /** Filter contacts by seniority level
     * @default []
     */
    seniorityLevels?: Array<'c-suite' | 'director' | 'entry' | 'founder' | 'head' | 'intern' | 'manager' | 'owner' | 'partner' | 'senior' | 'vp'>;
  };
};

export type LoneScaleV1ContactSourceNode = {
  type: 'n8n-nodes-base.loneScale';
  version: 1;
  config: NodeConfig<LoneScaleV1ContactSourceParams> & { credentials?: Credentials };
};